scwin.trigger2_onclick = function(e) {
    //model.setValue("root/ui/elagList/elagList_row[" + (1) + "]/elagSelCat", "1");
    WebSquare.ModelUtil.setInstanceValue({
        xpath: "root/ui/elagList/elagList_row[" + (1) + "]/elagSelCat",
        instanceId: "",
        value: "1"
    });
};
scwin.rgb2hex = function(rgb) {
    rgb = rgb.match(/^rgba?[\s+]?\([\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?/i);
    return (rgb && rgb.length === 4) ? "#" +
        ("0" + parseInt(rgb[1], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[2], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[3], 10).toString(16)).slice(-2) : '';
}
scwin._checkRgb = function(id, hexa) {
    var rgb = WebSquare.wUnit.getJq("#" + id).css("background-color");
    var color;
    if (rgb.indexOf("rgb") != -1) {
        color = scwin.rgb2hex(rgb);
        return color == hexa;
    }
    return rgb == hexa;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 'setRowVisible'버튼을 클릭한다.
    //1. After running the sample, click the 'setRowVisible' button.
    //Verify step 1. 044. The color of the illness (disease-specific high-altitude collateral) part is changed to greenish color.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin._checkRgb($p.id+'dgr_plnElagGrid_cell_42_0', '#ddff99')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 그상태에서 'setValue'버튼을 클릭한다.
    //2. In that state, click the 'setValue' button.
    //Verify step 2. It is shown to be kept green in 044 same color.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin._checkRgb($p.id+'dgr_plnElagGrid_cell_42_0', '#ddff99')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 06-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
